/**
 * The laboratory's logo, embedded as a data URL.
 *
 * The report renderers only accept `data:` image URLs — the print DOM, the
 * jsPDF letterhead and the stored profile all carry the same string — so the
 * shipped logo lives here rather than as a file the page would have to fetch.
 *
 * Source: `src-tauri/icons/adarsh_lab_logo.png` (259 x 220 PNG). Regenerate
 * with: `base64 -i src-tauri/icons/adarsh_lab_logo.png`.
 */
export const DEFAULT_LOGO_DATA_URL =
  "data:image/png;base64,";
